-- LOCAL PRO ONLY. Private commercial attribution. Never rewrites legacy sourceLabel,
-- entry kind, appointments, stages, forecasts, messages or access permissions.
begin;
create table if not exists pro_lead_origin_channels(owner_id uuid not null references profiles(id)on delete cascade,id text not null,name_override text check(length(btrim(name_override))between 1 and 80 and name_override!~'[[:cntrl:]]'),archived boolean not null default false,revision integer not null check(revision>=0),created_at timestamptz,updated_at timestamptz,primary key(owner_id,id),check(id in('direct','referral','website','social','advertising','other')or(id~'^[a-f0-9-]{36}$'and name_override is not null)),check((revision=0 and not archived and id in('direct','referral','website','social','advertising','other')and name_override is null and created_at is null and updated_at is null)or(revision>0 and created_at is not null and updated_at is not null)));
create table if not exists pro_lead_origin_assignments(owner_id uuid not null references profiles(id)on delete cascade,kind text not null check(kind in('manual','request')),id uuid not null,manual_id uuid,manual_kind text not null default'manual'check(manual_kind='manual'),request_id uuid,channel_id text check(channel_id in('direct','referral','website','social','advertising','other')or channel_id~'^[a-f0-9-]{36}$'),custom_channel_id text generated always as(case when channel_id in('direct','referral','website','social','advertising','other')then null else channel_id end)stored,revision integer not null check(revision>0),updated_at timestamptz not null default now(),primary key(owner_id,kind,id),foreign key(owner_id,manual_kind,manual_id)references pro_lead_center_records(owner_id,kind,id)on delete cascade,foreign key(owner_id,request_id)references pro_appointment_requests(owner_id,id)on delete cascade,foreign key(owner_id,custom_channel_id)references pro_lead_origin_channels(owner_id,id),check((kind='manual'and manual_id is not null and manual_id=id and request_id is null)or(kind='request'and request_id is not null and request_id=id and manual_id is null)));
create index if not exists pro_lead_origin_channel_refs on pro_lead_origin_assignments(owner_id,channel_id,kind,id);
create table if not exists pro_lead_origin_actions(owner_id uuid not null references profiles(id)on delete cascade,action_id uuid not null,input jsonb not null,result jsonb not null,at timestamptz not null default now(),primary key(owner_id,action_id));
create table if not exists pro_lead_origin_history(owner_id uuid not null,kind text not null,id uuid not null,action_id uuid not null,action text not null check(action in('assign','clear')),before_origin jsonb not null,after_origin jsonb not null,at timestamptz not null default now(),primary key(owner_id,action_id),foreign key(owner_id,kind,id)references pro_lead_origin_assignments(owner_id,kind,id)on delete cascade);
create index if not exists pro_lead_origin_history_page on pro_lead_origin_history(owner_id,kind,id,((after_origin->>'revision')::integer)desc);
create or replace function public.pro_lead_origin_owner(p_actor uuid)returns void language plpgsql stable security invoker set search_path=public,pg_temp as $$begin
 -- Single Pro entitlement rule (pro_entitled, pro-entitled-draft.sql): hasProAccess plus the ban check.
 -- No public-directory/profile prerequisite.
 -- The service-only HTTP boundary separately checks admin MFA.
 perform public.pro_entitled_require(p_actor);end $$;
create or replace function public.pro_lead_origin_stage_catalog(p_actor uuid) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$declare stages jsonb;begin perform pro_lead_origin_owner(p_actor);
 with defaults as(select v id,(n-1)::integer position from unnest(array['new','followed_up','connected','meeting_scheduled','estimate_sent','won']) with ordinality x(v,n)),all_stages as(select d.id,coalesce(s.position,d.position)position,s.name,coalesce(s.hidden,false)hidden,s.reassign_to_id,true builtin from defaults d left join pro_request_pipeline_stages s on s.owner_id=p_actor and s.id=d.id union all select id,position,name,hidden,reassign_to_id,false from pro_request_pipeline_stages where owner_id=p_actor and not retired and id not in('new','followed_up','connected','meeting_scheduled','estimate_sent','won')) select jsonb_agg(jsonb_build_object('id',id,'builtin',builtin,'name',name,'position',position,'hidden',hidden,'reassignToId',reassign_to_id) order by position) into stages from all_stages;
 return jsonb_build_object('revision',coalesce((select revision from pro_request_pipeline_heads where owner_id=p_actor),0),'stages',stages);end $$;
create or replace function public.pro_lead_origin_request(p_actor uuid,p_request uuid) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$declare r pro_appointment_requests;state jsonb;automatic jsonb;record jsonb;effective text;followup pro_request_followups;begin
 perform pro_lead_origin_owner(p_actor);select * into r from pro_appointment_requests where owner_id=p_actor and id=p_request;if not found then raise exception 'Request unavailable' using errcode='P0002';end if;state:=pro_request_pipeline_state(p_actor,p_request);automatic:=pro_request_pipeline_auto(p_actor,p_request);record:=pro_appointment_record(p_actor,p_request);effective:=coalesce(state->>'stageId',automatic->>'stageId');select coalesce(reassign_to_id,effective) into effective from pro_request_pipeline_stages where owner_id=p_actor and id=effective;effective:=coalesce(effective,state->>'stageId',automatic->>'stageId');
 select * into followup from pro_request_followups where owner_id=p_actor and request_id=p_request;
 return jsonb_build_object('requestId',r.id,'position',r.position,'service',r.service,'clientName',r.client_name,'publicStatus',r.status,'requestRevision',r.revision,'createdAt',r.created_at,'updatedAt',r.updated_at,'start',record->'start','workId',r.work_id,'workCancelled',record->'workCancelled','state',state,'effectiveStageId',effective,'automaticStageId',automatic->'stageId','evidence',automatic->'evidence','followup',pro_request_followup_json(followup,r.id));end $$;
create or replace function public.pro_lead_origin_item(p_actor uuid,p_kind text,p_id uuid) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$declare r pro_lead_center_records;c pro_clients;begin
 perform pro_lead_origin_owner(p_actor);if p_kind is null or p_kind not in('manual','request') then raise exception 'Invalid lead source' using errcode='22023';end if;select * into r from pro_lead_center_records where owner_id=p_actor and kind=p_kind and id=p_id;
 if p_kind='manual' then if not found then raise exception 'Opportunity unavailable' using errcode='P0002';end if;select * into c from pro_clients where user_id=p_actor and id=r.client_id;return jsonb_build_object('kind','manual','id',r.id,'manual',pro_lead_center_manual_json(r),'client',jsonb_build_object('id',c.id,'name',c.name,'archived',c.archived));end if;
 if not exists(select 1 from pro_appointment_requests where owner_id=p_actor and id=p_id) then raise exception 'Request unavailable' using errcode='P0002';end if;return jsonb_build_object('kind','request','id',p_id,'request',pro_lead_origin_request(p_actor,p_id),'preference',jsonb_build_object('revision',coalesce(r.revision,0),'archived',coalesce(r.archived,false),'updatedAt',r.updated_at));end $$;
create or replace function public.pro_lead_origin_catalog(p_actor uuid)returns table(id text,name text,custom_name boolean,builtin boolean,archived boolean,revision integer,created_at timestamptz,updated_at timestamptz)language plpgsql stable security invoker set search_path=public,pg_temp as $$begin perform pro_lead_origin_owner(p_actor);return query
 with defaults(id,label)as(values('direct','Direct'),('referral','Referral'),('website','Website'),('social','Social media'),('advertising','Advertising'),('other','Other'))
 select d.id,coalesce(c.name_override,d.label),c.name_override is not null,true,coalesce(c.archived,false),coalesce(c.revision,0),c.created_at,c.updated_at from defaults d left join pro_lead_origin_channels c on c.owner_id=p_actor and c.id=d.id
 union all select c.id,c.name_override,true,false,c.archived,c.revision,c.created_at,c.updated_at from pro_lead_origin_channels c where c.owner_id=p_actor and c.id not in('direct','referral','website','social','advertising','other');end $$;
create or replace function public.pro_lead_origin_channel_json(p_actor uuid,p_id text)returns jsonb language sql stable security invoker set search_path=public,pg_temp as $$select jsonb_build_object('id',c.id,'name',c.name,'customName',c.custom_name,'builtin',c.builtin,'archived',c.archived,'revision',c.revision,'createdAt',c.created_at,'updatedAt',c.updated_at)from pro_lead_origin_catalog(p_actor)c where c.id=p_id$$;
create or replace function public.pro_lead_origin_get(p_actor uuid,p_kind text,p_id uuid)returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$declare source jsonb;a pro_lead_origin_assignments;can_write boolean;begin
 perform pro_lead_origin_owner(p_actor);source:=pro_lead_origin_item(p_actor,p_kind,p_id);select*into a from pro_lead_origin_assignments where owner_id=p_actor and kind=p_kind and id=p_id;
 can_write:=case when p_kind='manual'then not(source->'manual'->>'archived')::boolean and not(source->'client'->>'archived')::boolean else not(source->'preference'->>'archived')::boolean and not exists(select 1 from pro_clients c join pro_appointment_requests r on r.owner_id=c.user_id and c.id='reservation-'||r.client_user_id::text where r.owner_id=p_actor and r.id=p_id and c.archived)end;
 return jsonb_build_object('kind',p_kind,'id',p_id,'entryKind',case when p_kind='manual'then'manual'else'contratacr'end,'channel',pro_lead_origin_channel_json(p_actor,a.channel_id),'legacyLabel',case when p_kind='manual'then source->'manual'->>'sourceLabel'else''end,'revision',coalesce(a.revision,0),'updatedAt',a.updated_at,'canWrite',can_write);end $$;
create or replace function public.pro_lead_origin_action_read(p_actor uuid,p_action uuid)returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$declare r pro_lead_origin_actions;begin
 perform pro_lead_origin_owner(p_actor);select*into r from pro_lead_origin_actions where owner_id=p_actor and action_id=p_action;if not found then return jsonb_build_object('receipt',null);end if;if r.result->>'type'='origin'then perform pro_lead_origin_get(p_actor,r.input->>'kind',(r.input->>'id')::uuid);end if;return jsonb_build_object('receipt',jsonb_build_object('input',r.input,'result',r.result));end $$;
create or replace function public.pro_lead_origin_history_read(p_actor uuid,p_kind text,p_id uuid,p_after uuid default null)returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$declare rev integer;items jsonb;cursor_id uuid;begin
 perform pro_lead_origin_get(p_actor,p_kind,p_id);if p_after is not null then select(after_origin->>'revision')::integer into rev from pro_lead_origin_history where owner_id=p_actor and kind=p_kind and id=p_id and action_id=p_after;if not found then raise exception'History cursor changed'using errcode='40001';end if;end if;
 select coalesce(jsonb_agg(content order by revision desc),'[]')into items from(select(after_origin->>'revision')::integer revision,jsonb_build_object('actionId',action_id,'action',action,'at',at,'before',before_origin,'after',after_origin)content from pro_lead_origin_history where owner_id=p_actor and kind=p_kind and id=p_id and(p_after is null or(after_origin->>'revision')::integer<rev)order by(after_origin->>'revision')::integer desc limit 21)h;
 if jsonb_array_length(items)>20 then cursor_id:=(items->19->>'actionId')::uuid;items:=items-20;end if;return jsonb_build_object('items',items,'nextCursor',cursor_id);end $$;
create or replace function public.pro_lead_origin_context(p_actor uuid,p_kind text,p_id uuid)returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$declare origin jsonb;h jsonb;begin origin:=pro_lead_origin_get(p_actor,p_kind,p_id);h:=pro_lead_origin_history_read(p_actor,p_kind,p_id);return jsonb_build_object('origin',origin,'history',h->'items','nextCursor',h->'nextCursor');end $$;
create or replace function public.pro_lead_origin_batch(p_actor uuid,p_refs jsonb)returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$declare r jsonb;items jsonb:='[]';seen text[]:=array[]::text[];k text;begin perform pro_lead_origin_owner(p_actor);if jsonb_typeof(p_refs)is distinct from'array'or jsonb_array_length(p_refs)>20 then raise exception'Invalid references'using errcode='22023';end if;
 for r in select value from jsonb_array_elements(p_refs)loop if jsonb_typeof(r)is distinct from'object'or not(r?&array['kind','id'])or exists(select 1 from jsonb_object_keys(r)key where key<>all(array['kind','id']))or r->>'kind'not in('manual','request')or jsonb_typeof(r->'id')is distinct from'string'then raise exception'Invalid reference'using errcode='22023';end if;k:=(r->>'kind')||':'||(r->>'id');if k=any(seen)then raise exception'Duplicate reference'using errcode='22023';end if;seen:=array_append(seen,k);items:=items||jsonb_build_array(pro_lead_origin_get(p_actor,r->>'kind',(r->>'id')::uuid));end loop;return jsonb_build_object('items',items);end $$;
create or replace function public.pro_lead_origin_channels_read(p_actor uuid,p_status text default'active',p_query text default'',p_after text default null,p_snapshot text default null)returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$declare answer jsonb;begin
 perform pro_lead_origin_owner(p_actor);if p_status not in('active','archived')or p_status is null or p_query is null or length(p_query)>100 or(p_after is null)<>(p_snapshot is null)then raise exception'Invalid channel query'using errcode='22023';end if;
 with channels as materialized(select*from pro_lead_origin_catalog(p_actor)where archived=(p_status='archived')and(btrim(p_query)=''or exists(select 1 from unnest(pro_lead_origin_name_aliases(id,name,custom_name))alias where position(lower(btrim(p_query))in alias)>0))),metadata as(select md5(p_actor::text||p_status||p_query||coalesce(jsonb_agg(to_jsonb(c)order by id)::text,'[]'))token from channels c),page as(select*from channels where p_after is null or id>p_after order by id limit 21)
 select jsonb_build_object('fingerprint',(select token from metadata),'items',coalesce((select jsonb_agg(pro_lead_origin_channel_json(p_actor,id)order by id)from(select*from page order by id limit 20)p),'[]'),'nextCursor',case when(select count(*)from page)>20 then(select id from page order by id offset 19 limit 1)else null end,'validCursor',p_after is null or exists(select 1 from channels where id=p_after))into answer;
 if p_after is not null and(p_snapshot is distinct from answer->>'fingerprint'or not(answer->>'validCursor')::boolean)then raise exception'Channels changed'using errcode='40001';end if;return answer-'validCursor';end $$;
-- Only the six explicit built-in translations are aliases; never infer channels.
create or replace function public.pro_lead_origin_name_aliases(p_id text,p_name text,p_custom boolean)returns text[]language sql immutable security invoker set search_path=public,pg_temp as $$select array_remove(array[lower(btrim(p_name)),case when not p_custom then lower(case p_id when'direct'then'Contacto directo'when'referral'then'Recomendación'when'website'then'Sitio web'when'social'then'Redes sociales'when'advertising'then'Publicidad'when'other'then'Otro'end)else null end],null)$$;
create or replace function public.pro_lead_origin_mutate(p_actor uuid,p_input jsonb)returns jsonb language plpgsql security invoker set search_path=public,pg_temp as $$declare aid uuid;act text;cid text;rev integer;r pro_lead_origin_actions;before_json jsonb;after_json jsonb;answer jsonb;keys text[];expected text[];n text;k text;lid uuid;current_row pro_lead_origin_assignments;had_row boolean;begin
 perform pro_lead_origin_owner(p_actor);if jsonb_typeof(p_input)is distinct from'object'or jsonb_typeof(p_input->'action')is distinct from'string'or jsonb_typeof(p_input->'actionId')is distinct from'string'or jsonb_typeof(p_input->'revision')is distinct from'number'or not coalesce(p_input->>'revision'~'^[0-9]{1,10}$',false)or(p_input->>'revision')::numeric not between 0 and 2147483646 then raise exception'Invalid origin action'using errcode='22023';end if;
 act:=p_input->>'action';aid:=(p_input->>'actionId')::uuid;rev:=(p_input->>'revision')::integer;
 expected:=case act when'channel_create'then array['action','actionId','channelId','name','revision']when'channel_rename'then array['action','actionId','channelId','name','revision']when'channel_archive'then array['action','actionId','channelId','revision']when'channel_restore'then array['action','actionId','channelId','revision']when'assign'then array['action','actionId','channelId','channelRevision','id','kind','revision']when'clear'then array['action','actionId','id','kind','revision']else null end;
 select array_agg(key order by key)into keys from jsonb_object_keys(p_input)key;if expected is null or keys<>expected then raise exception'Invalid action fields'using errcode='22023';end if;
 if act<>'clear'then cid:=p_input->>'channelId';if jsonb_typeof(p_input->'channelId')is distinct from'string'or cid not in('direct','referral','website','social','advertising','other')and cid!~'^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$'then raise exception'Invalid channel'using errcode='22023';end if;end if;
 if act in('channel_create','channel_rename')then if jsonb_typeof(p_input->'name')is distinct from'string'then raise exception'Invalid name'using errcode='22023';end if;n:=btrim(p_input->>'name');if length(n)not between 1 and 80 or n~'[[:cntrl:]]'then raise exception'Invalid name'using errcode='22023';end if;end if;
 if act in('assign','clear')then k:=p_input->>'kind';if k is null or k not in('manual','request')or jsonb_typeof(p_input->'id')is distinct from'string'then raise exception'Invalid lead'using errcode='22023';end if;lid:=(p_input->>'id')::uuid;end if;
 if act='assign'and(jsonb_typeof(p_input->'channelRevision')is distinct from'number'or not coalesce(p_input->>'channelRevision'~'^[0-9]{1,10}$',false)or(p_input->>'channelRevision')::numeric not between 0 and 2147483647)then raise exception'Invalid channel revision'using errcode='22023';end if;
 perform pg_advisory_xact_lock(hashtextextended(p_actor::text,0));perform pg_advisory_xact_lock(hashtextextended('pro-lead-origin-action:'||p_actor::text||':'||aid::text,0));perform pg_advisory_xact_lock(hashtextextended('pro-lead-origin-catalog:'||p_actor::text,0));perform pro_lead_origin_owner(p_actor);
 select*into r from pro_lead_origin_actions where owner_id=p_actor and action_id=aid;if found then if r.result->>'type'='origin'then perform pro_lead_origin_get(p_actor,r.input->>'kind',(r.input->>'id')::uuid);end if;if r.input is distinct from p_input then raise exception'Action identity reused'using errcode='22023';end if;return r.result;end if;
 if act like'channel_%'then
 before_json:=pro_lead_origin_channel_json(p_actor,cid);
 if act='channel_create'then if rev<>0 or before_json is not null or cid in('direct','referral','website','social','advertising','other')then raise exception'Channel identity exists'using errcode='40001';end if;
 else if before_json is null or(before_json->>'revision')::integer<>rev then raise exception'Channel changed'using errcode='40001';end if;if act='channel_restore'then if not(before_json->>'archived')::boolean then raise exception'Channel is not archived'using errcode='22023';end if;elsif(before_json->>'archived')::boolean then raise exception'Restore the channel before changing it'using errcode='40001';end if;end if;
 if act in('channel_create','channel_rename','channel_restore')and exists(select 1 from pro_lead_origin_catalog(p_actor)c where c.id<>cid and not c.archived and pro_lead_origin_name_aliases(c.id,c.name,c.custom_name)&&pro_lead_origin_name_aliases(cid,coalesce(n,before_json->>'name'),case when act in('channel_create','channel_rename')then true else coalesce((before_json->>'customName')::boolean,true)end))then raise exception'An active channel already uses this name'using errcode='40001';end if;
 insert into pro_lead_origin_channels(owner_id,id,name_override,archived,revision,created_at,updated_at)values(p_actor,cid,case when act in('channel_create','channel_rename')then n when coalesce((before_json->>'customName')::boolean,false)then before_json->>'name'else null end,act='channel_archive',rev+1,now(),now())on conflict(owner_id,id)do update set name_override=case when act='channel_rename'then n else pro_lead_origin_channels.name_override end,archived=case when act='channel_archive'then true when act='channel_restore'then false else pro_lead_origin_channels.archived end,revision=rev+1,created_at=coalesce(pro_lead_origin_channels.created_at,now()),updated_at=now();
 after_json:=pro_lead_origin_channel_json(p_actor,cid);answer:=jsonb_build_object('type','channel','action',act,'channel',after_json,'before',before_json);
 else
 perform pg_advisory_xact_lock(hashtextextended('pro-lead-origin:'||p_actor::text||':'||k||':'||lid::text,0));
 -- Manual commercial writers share owner->lead order. Public requests are only
 -- read/rechecked, avoiding request->work/owner lock inversion in booking writers.
 if k='manual'then perform 1 from pro_lead_center_records where owner_id=p_actor and kind='manual'and id=lid for update;end if;
 perform pro_lead_origin_owner(p_actor);before_json:=pro_lead_origin_get(p_actor,k,lid);if not(before_json->>'canWrite')::boolean or(before_json->>'revision')::integer<>rev then raise exception'Lead attribution changed or is read-only'using errcode='40001';end if;
 if act='assign'then after_json:=pro_lead_origin_channel_json(p_actor,cid);if after_json is null or(after_json->>'archived')::boolean or(after_json->>'revision')::integer<>(p_input->>'channelRevision')::integer then raise exception'Choose a current active channel'using errcode='40001';end if;
 end if;
 select*into current_row from pro_lead_origin_assignments where owner_id=p_actor and kind=k and id=lid for update;had_row:=found;if had_row and current_row.revision<>rev or not had_row and rev<>0 then raise exception'Attribution changed'using errcode='40001';end if;
 insert into pro_lead_origin_assignments(owner_id,kind,id,manual_id,request_id,channel_id,revision)values(p_actor,k,lid,case when k='manual'then lid else null end,case when k='request'then lid else null end,case when act='assign'then cid else null end,rev+1)on conflict(owner_id,kind,id)do update set channel_id=excluded.channel_id,revision=excluded.revision,updated_at=now();
 after_json:=pro_lead_origin_get(p_actor,k,lid);if not(after_json->>'canWrite')::boolean then raise exception'Lead became read-only'using errcode='40001';end if;answer:=jsonb_build_object('type','origin','action',act,'origin',after_json,'before',before_json);insert into pro_lead_origin_history(owner_id,kind,id,action_id,action,before_origin,after_origin)values(p_actor,k,lid,aid,act,before_json,after_json);
 end if;
 perform pro_lead_origin_owner(p_actor);insert into pro_lead_origin_actions(owner_id,action_id,input,result)values(p_actor,aid,p_input,answer);return answer;end $$;
create or replace function public.pro_lead_origin_list(p_actor uuid,p_status text default 'active',p_stage text default null,p_query text default '',p_channel text default null,p_after text default null,p_snapshot text default null) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$declare catalog jsonb;answer jsonb;actual_token text;cursor_valid boolean;begin
 perform pro_lead_origin_owner(p_actor);catalog:=pro_lead_origin_stage_catalog(p_actor);if p_status is null or p_status not in('active','archived') or p_query is null or length(p_query)>100 or p_stage is not null and not exists(select 1 from jsonb_array_elements(catalog->'stages')s where s->>'id'=p_stage) or p_after is not null and p_after!~'^(manual|request):[a-f0-9-]{36}$' then raise exception 'Invalid lead query' using errcode='22023';end if;
 if(p_after is null)<>(p_snapshot is null)or(p_channel is not null and p_channel<>'unspecified'and pro_lead_origin_channel_json(p_actor,p_channel)is null)then raise exception'Invalid attribution filter'using errcode='22023';end if;
 with sources as materialized(select s.*,a.channel_id,coalesce(a.revision,0)origin_revision,case when s.kind='request'then exists(select 1 from pro_clients c join pro_appointment_requests r on r.owner_id=c.user_id and c.id='reservation-'||r.client_user_id::text where r.owner_id=p_actor and r.id=s.id and c.archived)else false end private_client_archived from pro_lead_center_sources(p_actor,p_status='archived',p_query)s left join pro_lead_origin_assignments a on a.owner_id=p_actor and a.kind=s.kind and a.id=s.id where p_channel is null or p_channel='unspecified'and a.channel_id is null or a.channel_id=p_channel),
 metadata as(select md5(p_actor::text||p_status||coalesce(p_stage,'all')||p_query||coalesce(p_channel,'all')||catalog::text||(select coalesce(jsonb_agg(to_jsonb(c)order by id)::text,'[]')from pro_lead_origin_catalog(p_actor)c)||coalesce(string_agg(jsonb_build_array(kind,id,created_at,effective_stage,fingerprint,channel_id,origin_revision,private_client_archived)::text,',' order by created_at desc,kind,id desc),''))token from sources),
 anchor as(select * from sources where kind=split_part(p_after,':',1) and id=split_part(p_after,':',2)::uuid and(p_stage is null or effective_stage=p_stage)),
 selected as materialized(select * from sources where(p_stage is null or effective_stage=p_stage) and(p_after is null or created_at<(select created_at from anchor) or created_at=(select created_at from anchor) and(kind>(select kind from anchor) or kind=(select kind from anchor) and id<(select id from anchor))) order by created_at desc,kind,id desc limit 21),
 page as(select coalesce(jsonb_agg(pro_lead_origin_item(p_actor,kind,id) order by created_at desc,kind,id desc),'[]'::jsonb)items from(select * from selected order by created_at desc,kind,id desc limit 20)v),
 counts as(select jsonb_agg(jsonb_build_object('stageId',s->>'id','count',(select count(*) from sources where effective_stage=s->>'id')) order by(s->>'position')::integer)items from jsonb_array_elements(catalog->'stages')s)
 select jsonb_build_object('catalog',catalog,'items',page.items,'counts',counts.items,'nextCursor',case when(select count(*) from selected)>20 then(select kind||':'||id::text from selected order by created_at desc,kind,id desc offset 19 limit 1)else null end,'snapshotToken',metadata.token),metadata.token,(p_after is null or exists(select 1 from anchor)) into answer,actual_token,cursor_valid from page cross join counts cross join metadata;
 if p_after is not null and(p_snapshot is null or p_snapshot<>actual_token or not cursor_valid) then raise exception 'Leads changed; refresh before continuing' using errcode='40001';end if;return jsonb_build_object('page',answer,'context',coalesce((select jsonb_agg(pro_lead_origin_get(p_actor,i->>'kind',(i->>'id')::uuid)order by n)from jsonb_array_elements(answer->'items')with ordinality x(i,n)),'[]'));end $$;
create or replace function public.pro_lead_origin_metrics(p_actor uuid,p_status text default'active',p_stage text default null,p_query text default'',p_from date default null,p_to date default null,p_after text default null,p_snapshot text default null)returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$declare answer jsonb;catalog jsonb;begin
 perform pro_lead_origin_owner(p_actor);catalog:=pro_lead_origin_stage_catalog(p_actor);
 if p_status is null or p_status not in('active','archived')or p_query is null or length(p_query)>100 or p_stage is not null and not exists(select 1 from jsonb_array_elements(catalog->'stages')s where s->>'id'=p_stage)or(p_after is null)<>(p_snapshot is null)or p_from is not null and p_from not between date'1900-01-01'and date'2100-12-31'or p_to is not null and p_to not between date'1900-01-01'and date'2100-12-31'or p_from>p_to then raise exception'Invalid metrics query'using errcode='22023';end if;
 with sources as materialized(select s.*,a.channel_id,coalesce(a.revision,0)origin_revision,case when s.kind='request'then exists(select 1 from pro_clients c join pro_appointment_requests r on r.owner_id=c.user_id and c.id='reservation-'||r.client_user_id::text where r.owner_id=p_actor and r.id=s.id and c.archived)else false end private_client_archived from pro_lead_center_sources(p_actor,p_status='archived',p_query)s left join pro_lead_origin_assignments a on a.owner_id=p_actor and a.kind=s.kind and a.id=s.id where(p_stage is null or s.effective_stage=p_stage)and(p_from is null or(s.created_at at time zone'America/Costa_Rica')::date>=p_from)and(p_to is null or(s.created_at at time zone'America/Costa_Rica')::date<=p_to)),
 groups as(select channel_id,count(*)filter(where kind='manual')manual,count(*)filter(where kind='request')request,count(*)total,count(*)filter(where effective_stage='won')won from sources group by channel_id),
 rows as(select 'unspecified'::text id,'0'::text ordering,null::text channel_id,coalesce(g.manual,0)manual,coalesce(g.request,0)request,coalesce(g.total,0)total,coalesce(g.won,0)won from(select 1)dummy left join groups g on g.channel_id is null union all select channel_id,'1:'||channel_id,channel_id,manual,request,total,won from groups where channel_id is not null),
 metadata as(select md5(p_actor::text||p_status||coalesce(p_stage,'all')||p_query||coalesce(p_from::text,'')||coalesce(p_to::text,'')||catalog::text||(select coalesce(jsonb_agg(to_jsonb(c)order by id)::text,'[]')from pro_lead_origin_catalog(p_actor)c)||coalesce(jsonb_agg(jsonb_build_array(kind,id,fingerprint,effective_stage,channel_id,origin_revision,private_client_archived)order by created_at desc,kind,id desc)::text,'[]'))token from sources),
 page as(select*from rows where p_after is null or ordering>(case when p_after='unspecified'then'0'else'1:'||p_after end)order by ordering limit 21)
 select jsonb_build_object('fingerprint',(select token from metadata),'items',coalesce((select jsonb_agg(jsonb_build_object('channel',pro_lead_origin_channel_json(p_actor,channel_id),'manual',manual,'request',request,'total',total,'won',won)order by ordering)from(select*from page order by ordering limit 20)p),'[]'),'totals',(select jsonb_build_object('manual',count(*)filter(where kind='manual'),'request',count(*)filter(where kind='request'),'total',count(*),'won',count(*)filter(where effective_stage='won'))from sources),'nextCursor',case when(select count(*)from page)>20 then(select id from page order by ordering offset 19 limit 1)else null end,'validCursor',p_after is null or exists(select 1 from rows where id=p_after))into answer;
 if p_after is not null and(p_snapshot is distinct from answer->>'fingerprint'or not(answer->>'validCursor')::boolean)then raise exception'Metrics changed'using errcode='40001';end if;return answer-'validCursor';end $$;
create or replace function public.pro_lead_origin_immutable()returns trigger language plpgsql security invoker set search_path=public,pg_temp as $$begin raise exception'Immutable commercial attribution audit'using errcode='23514';end $$;
drop trigger if exists pro_lead_origin_actions_immutable on pro_lead_origin_actions;
create trigger pro_lead_origin_actions_immutable before update on pro_lead_origin_actions for each row execute function pro_lead_origin_immutable();
drop trigger if exists pro_lead_origin_history_immutable on pro_lead_origin_history;
create trigger pro_lead_origin_history_immutable before update on pro_lead_origin_history for each row execute function pro_lead_origin_immutable();
alter table pro_lead_origin_channels enable row level security;alter table pro_lead_origin_assignments enable row level security;alter table pro_lead_origin_actions enable row level security;alter table pro_lead_origin_history enable row level security;
revoke all on pro_lead_origin_channels,pro_lead_origin_assignments,pro_lead_origin_actions,pro_lead_origin_history from public,anon,authenticated;grant all on pro_lead_origin_channels,pro_lead_origin_assignments,pro_lead_origin_actions,pro_lead_origin_history to service_role;
do $$declare f record;begin for f in select p.oid::regprocedure signature from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname like'pro_lead_origin_%'loop execute format('revoke all on function %s from public,anon,authenticated',f.signature);execute format('grant execute on function %s to service_role',f.signature);end loop;end $$;
commit;
notify pgrst,'reload schema';
